from collections import Counter

def get_pair_stats(vocab):
    pairs = Counter()
    for word, freq in vocab.items():
        symbols = word.split()
        for i in range(len(symbols) - 1):
            pairs[(symbols[i], symbols[i + 1])] += freq
    return pairs

def merge_pair(vocab, pair):
    bigram = ' '.join(pair)
    replacement = ''.join(pair)
    new_vocab = {}
    for word, freq in vocab.items():
        new_word = word.replace(bigram, replacement)
        new_vocab[new_word] = freq
    return new_vocab

def bpe_encode(word, merges):
    symbols = list(word)
    for pair in merges:
        i = 0
        while i < len(symbols) - 1:
            if (symbols[i], symbols[i + 1]) == pair:
                symbols[i] = symbols[i] + symbols[i + 1]
                symbols.pop(i + 1)
            else:
                i += 1
    return symbols

if __name__ == "__main__":
    vocab = {
        'l o w': 5,
        'l o w e r': 2,
        'w i d e r': 3,
        'n e w e r': 6
    }
    stats = get_pair_stats(vocab)
    print("Pair frequencies:", stats.most_common(5))
    best_pair = stats.most_common(1)[0][0]
    print("Best pair:", best_pair)
    new_vocab = merge_pair(vocab, best_pair)
    print("After merge:", new_vocab)

    merges = [('e', 'r'), ('o', 'w')]
    print("BPE encode 'lower':", bpe_encode("lower", merges))

import numpy as np
from collections import Counter
from math import log

class SimpleTFIDF:
    def __init__(self):
        self.vocab_ = {}
        self.idf_ = {}

    def fit(self, documents):
        N = len(documents)
        df = Counter()
        for doc in documents:
            unique = set(doc.lower().split())
            df.update(unique)
        self.vocab_ = {word: i for i, word in enumerate(sorted(df.keys()))}
        for word, freq in df.items():
            self.idf_[word] = log(N / (freq + 1)) + 1.0

    def transform(self, documents):
        n_features = len(self.vocab_)
        matrix = np.zeros((len(documents), n_features))
        for i, doc in enumerate(documents):
            words = doc.lower().split()
            counts = Counter(words)
            total = len(words)
            for word, cnt in counts.items():
                if word in self.vocab_:
                    tf = cnt / total
                    matrix[i, self.vocab_[word]] = tf * self.idf_[word]
        return matrix

    def cosine_similarity(self, vec_a, vec_b):
        dot = np.dot(vec_a, vec_b)
        norm_a = np.linalg.norm(vec_a)
        norm_b = np.linalg.norm(vec_b)
        if norm_a == 0 or norm_b == 0:
            return 0.0
        return dot / (norm_a * norm_b)

if __name__ == "__main__":
    docs = [
        "machine learning is great",
        "deep learning is powerful",
        "machine learning and deep learning"
    ]
    tfidf = SimpleTFIDF()
    tfidf.fit(docs)
    X = tfidf.transform(docs)
    print("TF-IDF matrix shape:", X.shape)
    print("Similarity doc1-doc2:", tfidf.cosine_similarity(X[0], X[1]))
    print("Similarity doc1-doc3:", tfidf.cosine_similarity(X[0], X[2]))

import numpy as np

def create_mlm_labels(tokens, mask_prob=0.15):
    MASK_ID = 103  # [MASK]
    tokens = list(tokens)
    labels = [-100] * len(tokens)
    masked_tokens = tokens[:]

    n_mask = max(1, int(len(tokens) * mask_prob))
    mask_indices = np.random.choice(len(tokens), n_mask, replace=False)

    for idx in mask_indices:
        labels[idx] = idx  # store original token id
        rand = np.random.random()
        if rand < 0.8:
            masked_tokens[idx] = '[MASK]'
        elif rand < 0.9:
            masked_tokens[idx] = tokens[np.random.randint(0, len(tokens))]
        # else: keep original

    return masked_tokens, labels

def bert_pooling(hidden_states, pooling='cls'):
    if pooling == 'cls':
        return hidden_states[0]
    elif pooling == 'mean':
        return np.mean(hidden_states, axis=0)
    else:
        raise ValueError(f"Unknown pooling: {pooling}")

if __name__ == "__main__":
    tokens = ['[CLS]', '我', '爱', '自然', '语言', '处理', '[SEP]']
    masked, labels = create_mlm_labels(tokens)
    print("Masked:", masked)
    print("Labels:", [l for l in labels if l != -100])
    hid = np.random.randn(7, 768)
    print("CLS vector shape:", bert_pooling(hid, 'cls').shape)
    print("Mean vector shape:", bert_pooling(hid, 'mean').shape)

import numpy as np

def softmax(logits, temperature=1.0):
    logits = logits / temperature
    exp_x = np.exp(logits - np.max(logits, axis=-1, keepdims=True))
    return exp_x / np.sum(exp_x, axis=-1, keepdims=True)

def greedy_sample(logits):
    return int(np.argmax(logits))

def top_k_sample(logits, k=50, temperature=1.0):
    probs = softmax(logits, temperature)
    # 只保留Top-k
    top_k_indices = np.argsort(logits)[::-1][:k]
    probs_filtered = np.zeros_like(probs)
    probs_filtered[top_k_indices] = probs[top_k_indices]
    probs_filtered /= np.sum(probs_filtered)
    return int(np.random.choice(len(probs_filtered), p=probs_filtered))

def top_p_sample(logits, p=0.9, temperature=1.0):
    probs = softmax(logits, temperature)
    sorted_idx = np.argsort(probs)[::-1]
    cumulative = np.cumsum(probs[sorted_idx])
    cutoff = np.searchsorted(cumulative, p) + 1
    keep = sorted_idx[:cutoff]
    probs_filt = np.zeros_like(probs)
    probs_filt[keep] = probs[keep]
    probs_filt /= np.sum(probs_filt)
    return int(np.random.choice(len(probs_filt), p=probs_filt))

class SimpleGPT:
    def __init__(self, vocab_size):
        self.vocab_size = vocab_size
    def forward(self, ids):
        return np.random.randn(1, len(ids), self.vocab_size)

def generate_text(model, prompt_ids, token_to_str, max_len=50, strategy='greedy'):
    generated = list(prompt_ids)
    for _ in range(max_len):
        logits = model.forward(generated)[0, -1, :]
        if strategy == 'greedy':
            next_token = greedy_sample(logits)
        elif strategy == 'top_k':
            next_token = top_k_sample(logits, k=50)
        elif strategy == 'top_p':
            next_token = top_p_sample(logits, p=0.9)
        else:
            next_token = greedy_sample(logits)
        generated.append(next_token)
        if next_token == 2:  # EOS
            break
    return generated

if __name__ == "__main__":
    logits = np.array([0.5, 2.0, 1.0, 0.3, 0.1])
    print("Greedy:", greedy_sample(logits))
    print("Top-k(k=3):", top_k_sample(logits, k=3))
    print("Top-p(p=0.9):", top_p_sample(logits, p=0.9))
